import { getComponentData, searchComponents } from '../utils/jsonDataLoader.js';

const REACT_BITS_RAW = 'https://raw.githubusercontent.com/davidhdev/react-bits/main';

/**
 * Get complete component code and documentation
 */
export async function getComponent(args) {
  const { 
    componentName, 
    version = 'js-css', 
    includeDemo = true 
  } = args;

  try {
    // Find component using JSON data
    let componentData;
    try {
      componentData = getComponentData(componentName, null, version);
    } catch (error) {
      // Try to find component by searching
      const searchResults = searchComponents(componentName, null, version, 1);
      if (searchResults.length === 0) {
        return {
          content: [
            {
              type: 'text',
              text: `Component "${componentName}" not found. Use search-react-bits-components to find available components.`
            }
          ]
        };
      }
      componentData = searchResults[0].data;
    }

    // Get all file contents from JSON data
    const componentCode = componentData.files.component.content;
    const cssCode = componentData.files.css?.content;
    const demoCode = includeDemo ? componentData.files.demo.content : null;
    
    // Get dependencies from component code
    const dependencies = await getDependencies(componentCode || '', version);

    // Format response using JSON data
    const responseText = formatComponentResponseFromJson(
      componentName,
      version,
      componentData,
      dependencies,
      includeDemo
    );

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error fetching component: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Get version directory based on tech stack
 */
function getVersionDirectory(version) {
  const versionMap = {
    'js-css': 'src/content',
    'js-tailwind': 'src/tailwind',
    'ts-css': 'src/ts-default',
    'ts-tailwind': 'src/ts-tailwind'
  };
  
  return versionMap[version] || 'src/content';
}

/**
 * Fetch component code from repository
 */
async function fetchComponentCode(componentName, versionDir, category) {
  const categoryMap = {
    'animations': 'Animations',
    'text-animations': 'TextAnimations',
    'components': 'Components',
    'backgrounds': 'Backgrounds'
  };

  const categoryDir = categoryMap[category] || 'Components';
  const componentPath = `${versionDir}/${categoryDir}/${componentName}/${componentName}.jsx`;
  
  try {
    const response = await fetch(`${REACT_BITS_RAW}/${componentPath}`);
    if (!response.ok) {
      // Try with different case variations
      const altPath = `${versionDir}/${categoryDir}/${capitalizeFirst(componentName)}/${capitalizeFirst(componentName)}.jsx`;
      const altResponse = await fetch(`${REACT_BITS_RAW}/${altPath}`);
      
      if (!altResponse.ok) {
        throw new Error(`Component file not found at ${componentPath}`);
      }
      
      return await altResponse.text();
    }
    
    return await response.text();
  } catch (error) {
    // Return placeholder code if file not found
    return generatePlaceholderCode(componentName, category);
  }
}

/**
 * Fetch demo code
 */
async function fetchDemoCode(componentName, category) {
  const categoryMap = {
    'animations': 'Animations',
    'text-animations': 'TextAnimations',
    'components': 'Components',
    'backgrounds': 'Backgrounds'
  };

  const categoryDir = categoryMap[category] || 'Components';
  const demoPath = `src/demo/${categoryDir}/${componentName}Demo.jsx`;
  
  try {
    const response = await fetch(`${REACT_BITS_RAW}/${demoPath}`);
    if (!response.ok) {
      // Try alternative naming
      const altPath = `src/demo/${categoryDir}/${capitalizeFirst(componentName)}Demo.jsx`;
      const altResponse = await fetch(`${REACT_BITS_RAW}/${altPath}`);
      
      if (!altResponse.ok) {
        return generateDemoPlaceholder(componentName);
      }
      
      return await altResponse.text();
    }
    
    return await response.text();
  } catch (error) {
    return generateDemoPlaceholder(componentName);
  }
}

/**
 * Extract dependencies from component code
 */
async function getDependencies(code, version) {
  const dependencies = [];
  const devDependencies = [];

  // Base React dependencies
  dependencies.push('react', 'react-dom');

  // Check for common libraries in the code
  if (code.includes('framer-motion')) dependencies.push('framer-motion');
  if (code.includes('@react-three/fiber')) dependencies.push('@react-three/fiber');
  if (code.includes('@react-three/drei')) dependencies.push('@react-three/drei');
  if (code.includes('three')) dependencies.push('three');
  if (code.includes('gsap')) dependencies.push('gsap');
  if (code.includes('@chakra-ui/react')) dependencies.push('@chakra-ui/react');
  if (code.includes('matter-js')) dependencies.push('matter-js');
  if (code.includes('react-use-gesture')) dependencies.push('react-use-gesture');

  // Version-specific dependencies
  if (version.includes('tailwind')) {
    dependencies.push('tailwindcss');
  }

  if (version.includes('ts')) {
    devDependencies.push('typescript', '@types/react', '@types/react-dom');
  }

  return {
    dependencies: [...new Set(dependencies)],
    devDependencies: [...new Set(devDependencies)]
  };
}

/**
 * Format component response from JSON data
 */
function formatComponentResponseFromJson(name, version, componentData, deps, includeDemo) {
  let output = `# ${componentData.name} Component\n\n`;
  
  output += `**Category:** ${componentData.category}\n`;
  output += `**Version:** ${version}\n`;
  output += `**Tech Stack:** ${componentData.techStack}\n`;
  output += `**Has CSS:** ${componentData.metadata.hasCSS ? 'Yes' : 'No'}\n`;
  output += `**TypeScript:** ${componentData.metadata.isTypeScript ? 'Yes' : 'No'}\n\n`;

  // Dependencies
  output += `## Dependencies\n\n`;
  output += `**Required packages:**\n`;
  deps.dependencies.forEach(dep => {
    output += `- ${dep}\n`;
  });

  if (deps.devDependencies.length > 0) {
    output += `\n**Dev dependencies:**\n`;
    deps.devDependencies.forEach(dep => {
      output += `- ${dep}\n`;
    });
  }

  // Installation
  output += `\n## Installation\n\n`;
  output += `\`\`\`bash\n`;
  output += `# Install via JSRepo CLI\n`;
  output += `jsrepo add react-bits/${name}\n\n`;
  output += `# Or install dependencies manually\n`;
  output += `npm install ${deps.dependencies.join(' ')}\n`;
  if (deps.devDependencies.length > 0) {
    output += `npm install -D ${deps.devDependencies.join(' ')}\n`;
  }
  output += `\`\`\`\n\n`;

  // Component Code
  if (componentData.files.component.content) {
    const fileExt = componentData.metadata.isTypeScript ? 'tsx' : 'jsx';
    output += `## Component Code (${componentData.files.component.filename})\n\n`;
    output += `\`\`\`${fileExt}\n${componentData.files.component.content}\n\`\`\`\n\n`;
  }

  // CSS Code (if available)
  if (componentData.files.css?.content) {
    output += `## CSS Styles (${componentData.files.css.filename})\n\n`;
    output += `\`\`\`css\n${componentData.files.css.content}\n\`\`\`\n\n`;
  }

  // Demo Code
  if (includeDemo && componentData.files.demo?.content) {
    output += `## Demo Usage (${componentData.files.demo.filename})\n\n`;
    output += `\`\`\`jsx\n${componentData.files.demo.content}\n\`\`\`\n\n`;
  }

  // Usage Notes
  output += `## Usage Notes\n\n`;
  output += `1. Make sure all dependencies are installed\n`;
  output += `2. Import the component into your React application\n`;
  output += `3. Customize props according to your needs\n`;
  if (componentData.metadata.isTailwind) {
    output += `4. Ensure Tailwind CSS is configured in your project\n`;
  }
  if (componentData.metadata.isTypeScript) {
    output += `4. TypeScript types are included for better development experience\n`;
  }
  if (componentData.files.css?.content) {
    output += `5. Import the CSS file for styling\n`;
  }

  output += `\n## File Paths\n\n`;
  output += `- Component: \`${componentData.files.component.filename}\`\n`;
  if (componentData.files.css) {
    output += `- Styles: \`${componentData.files.css.filename}\`\n`;
  }
  output += `- Demo: \`${componentData.files.demo.filename}\`\n`;

  return output;
}

/**
 * Format component response (legacy)
 */
function formatComponentResponse(name, version, component, code, demo, deps, includeDemo) {
  let output = `# ${capitalizeFirst(name)} Component\n\n`;
  
  output += `**Category:** ${component.category}\n`;
  output += `**Version:** ${version}\n`;
  output += `**Description:** ${component.description}\n\n`;

  // Dependencies
  output += `## Dependencies\n\n`;
  output += `**Required packages:**\n`;
  deps.dependencies.forEach(dep => {
    output += `- ${dep}\n`;
  });

  if (deps.devDependencies.length > 0) {
    output += `\n**Dev dependencies:**\n`;
    deps.devDependencies.forEach(dep => {
      output += `- ${dep}\n`;
    });
  }

  // Installation
  output += `\n## Installation\n\n`;
  output += `\`\`\`bash\n`;
  output += `# Install via JSRepo CLI\n`;
  output += `jsrepo add react-bits/${name}\n\n`;
  output += `# Or install dependencies manually\n`;
  output += `npm install ${deps.dependencies.join(' ')}\n`;
  if (deps.devDependencies.length > 0) {
    output += `npm install -D ${deps.devDependencies.join(' ')}\n`;
  }
  output += `\`\`\`\n\n`;

  // Component Code
  output += `## Component Code\n\n`;
  output += `\`\`\`jsx\n${code}\n\`\`\`\n\n`;

  // Demo Code
  if (includeDemo && demo) {
    output += `## Demo Usage\n\n`;
    output += `\`\`\`jsx\n${demo}\n\`\`\`\n\n`;
  }

  // Usage Notes
  output += `## Usage Notes\n\n`;
  output += `1. Make sure all dependencies are installed\n`;
  output += `2. Import the component into your React application\n`;
  output += `3. Customize props according to your needs\n`;
  if (version.includes('tailwind')) {
    output += `4. Ensure Tailwind CSS is configured in your project\n`;
  }
  if (version.includes('ts')) {
    output += `4. TypeScript types are included for better development experience\n`;
  }

  return output;
}

/**
 * Capitalize first letter
 */
function capitalizeFirst(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

/**
 * Generate placeholder code when component file is not found
 */
function generatePlaceholderCode(componentName, category) {
  return `// ${capitalizeFirst(componentName)} Component
// This is a placeholder - actual component code should be fetched from the repository

import React from 'react';

export default function ${capitalizeFirst(componentName)}(props) {
  return (
    <div className="${componentName}-container">
      <p>${capitalizeFirst(componentName)} component from React Bits</p>
      <p>Category: ${category}</p>
    </div>
  );
}`;
}

/**
 * Generate demo placeholder
 */
function generateDemoPlaceholder(componentName) {
  return `// Demo for ${capitalizeFirst(componentName)}
import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function ${capitalizeFirst(componentName)}Demo() {
  return (
    <div>
      <h2>${capitalizeFirst(componentName)} Demo</h2>
      <${capitalizeFirst(componentName)} />
    </div>
  );
}`;
}
